CREATE TABLE routing_operators(project_id TEXT NOT NULL,user_id TEXT NOT NULL,available INTEGER NOT NULL DEFAULT 0 CHECK(available IN (0,1)),capacity INTEGER NOT NULL DEFAULT 10 CHECK(capacity>=0 AND capacity<=10000),skills_json TEXT NOT NULL DEFAULT '[]',updated_at INTEGER NOT NULL,PRIMARY KEY(project_id,user_id),FOREIGN KEY(project_id,user_id) REFERENCES memberships(project_id,user_id) ON DELETE CASCADE);
CREATE TABLE routing_state(project_id TEXT NOT NULL,rule_id TEXT NOT NULL REFERENCES workflow_rules(id) ON DELETE CASCADE,revision INTEGER NOT NULL DEFAULT 0,last_user_id TEXT,PRIMARY KEY(project_id,rule_id));
CREATE TABLE routing_decisions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,event_id TEXT NOT NULL,rule_id TEXT NOT NULL,rule_name TEXT NOT NULL,version INTEGER NOT NULL,strategy TEXT NOT NULL,winner_id TEXT,group_id TEXT,overflow INTEGER NOT NULL DEFAULT 0,explanation TEXT NOT NULL,candidates_json TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(project_id,conversation_id,event_id));
CREATE INDEX routing_decisions_ticket ON routing_decisions(project_id,conversation_id,created_at);
CREATE TRIGGER workflow_routing_audit AFTER INSERT ON routing_decisions BEGIN
 INSERT INTO audit_events(id,project_id,at,category,action,outcome,actor_type,actor_id,source,target_type,target_id,detail_json) VALUES(lower(hex(randomblob(16))),NEW.project_id,NEW.created_at,'assignment','workflow.routed','succeeded','system',NEW.rule_id,'system','conversation',NEW.conversation_id,json_object('decision_id',NEW.id,'version',NEW.version,'strategy',NEW.strategy,'assignee',NEW.winner_id,'group_id',NEW.group_id,'overflow',NEW.overflow));
END;
